    // (внутри «гибрида»). Четыре буквы — минимум, на котором слово ещё
    // остаётся собой: «юниты» → «юнит», «почты» → «почт», «грейд» → «грей».
    .map((s) => (/^[а-яё]+$/.test(s) && s.length >= 5
      ? s.slice(0, Math.max(4, s.length - 2))
      : s));
}

